    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));
        String[] parts = br.readLine().split(" ");
        long n = Long.parseLong(parts[0]);
        long m = Long.parseLong(parts[1]);
        if (n > m) {
            long tmp = n;
            n = m;
            m = tmp;
        }
        if (n == 1) {
            long mod = m % 6;
            long result;
            if (mod == 0) result = n * m;
            else if (mod == 1) result = n * m - 1;
            else if (mod == 2) result = n * m - 2;
            else if (mod == 3) result = n * m - 3;
            else if (mod == 4) result = n * m - 2;
            else result = n * m - 1;
            pw.println(result);
        } else if (n == 2) {
            if (m == 2) pw.println(n * m - 4);
            else if (m == 3) pw.println(n * m - 2);
            else if (m == 7) pw.println(n * m - 2);
            else pw.println(n * m);
        } else if (n == 3) {
            if (m % 2 == 0) pw.println(n * m);
            else pw.println(n * m - 1);
        } else {
            if (n % 2 == 1 && m % 2 == 1) pw.println(n * m - 1);
            else pw.println(n * m);
        }
        pw.flush();
    }
}
